 Drawable tvHeaderNavBackground(boolean active,boolean focused){
 GradientDrawable base=new GradientDrawable();
 base.setCornerRadius(dp(18));
 base.setColor(focused?0x241fdc72:Color.TRANSPARENT);
 base.setStroke(dp(focused?2:0),focused?0xffe7fff0:Color.TRANSPARENT);
 if(!active&&!focused)return base;
 GradientDrawable line=new GradientDrawable();
 line.setCornerRadius(dp(2));
 line.setColor(focused?Color.WHITE:GREEN);
 LayerDrawable layer=new LayerDrawable(new Drawable[]{base,line});
 layer.setLayerInset(1,dp(12),dp(52),dp(12),dp(2));
 return layer;
}
void styleTvHeaderItem(TextView v,boolean active,boolean focused){
 if(v==null)return;
 v.setTypeface(android.graphics.Typeface.create(android.graphics.Typeface.SANS_SERIF,android.graphics.Typeface.BOLD_ITALIC));
 if(focused){
  v.setTextColor(Color.WHITE);
  v.setShadowLayer(0f,0f,0f,0);
  v.setScaleX(1.02f);v.setScaleY(1.02f);
  v.setBackground(tvHeaderNavBackground(active,true));
  if(android.os.Build.VERSION.SDK_INT>=21)v.setTranslationZ(dp(6));
 }else{
  v.setScaleX(1f);v.setScaleY(1f);
  if(android.os.Build.VERSION.SDK_INT>=21)v.setTranslationZ(0);
  v.setTextColor(active?0xff86ffb5:0xffeef4f0);
  v.setShadowLayer(active?0f:6f,0f,0f,active?0:0xaa000000);
  v.setBackground(tvHeaderNavBackground(active,false));
 }
}
