 void restoreHomeView(){
  // v16.211 TV-only: quando o app abre direto em TV, o host permanente da Home existe,
  // mas ainda esta vazio. Restaurar esse host vazio era a origem da tela totalmente verde.
  if(tvMode&&homeScrollCache!=null&&homeBodyCache!=null&&contentFrame!=null&&homeBodyCache.getChildCount()==0){attachPermanentHomeHost();homeViewAvailable=true;homeScrollY=0;homeTab("Recomendações");return;}
  if(homeViewAvailable&&homeScrollCache!=null&&homeBodyCache!=null&&contentFrame!=null){
   attachPermanentHomeHost();setNav(0);final int y=homeScrollY;mainScroll.setVisibility(View.VISIBLE);mainScroll.post(()->{mainScroll.scrollTo(0,y);mainScroll.requestLayout();});return;
  }
  // Fallback apenas se o host permanente ainda não existir (primeira montagem).
  attachPermanentHomeHost();home();
 }
 void goHomeNow(){
  releaseTvInlinePlayer();standardRootInsets();plansScreen=false;planFlowStage=0;providerSwitchScreen=false;searchScreenOpen=false;
  if(pixTimer!=null){try{pixTimer.cancel();}catch(Exception ignored){}pixTimer=null;}
  if(accessExpiredOverlay!=null)dismissAccessExpiredOverlay();
  if(detailOpen)closeDetails();
  if(navBar!=null)navBar.setVisibility(View.VISIBLE);
  if(contentFrame==null){shell();return;}
  restoreHomeView();
  // Guarda final: jamais deixa uma tela transitória visível com Início selecionado.
  if(mainScroll!=homeScrollCache||body!=homeBodyCache){attachPermanentHomeHost();setNav(0);}
 }
