 boolean accessDenied(JSONObject st){if(st==null)return false;return !st.optBoolean("allowed",st.optBoolean("active",true));}
 String accessDeniedMessage(JSONObject st){if(st==null)return "Assinatura inativa";String m=st.optString("message","").trim();if(!m.isEmpty())return m;String mode=st.optString("mode","").toLowerCase(java.util.Locale.ROOT);return mode.contains("trial")?"Seu teste grátis terminou":"Sua assinatura venceu";}
 void guardPlaybackAction(Runnable allowedAction){
  JSONObject cached=readCachedAccessStatus();if(accessDenied(cached)){showAccessExpiredDialog(accessDeniedMessage(cached));refreshEntitlements(null);return;}
  Api.post("access_status",Api.m("user_id",uid),new Api.CB(){public void ok(JSONObject j){JSONArray a=j.optJSONArray("result");JSONObject st=(a!=null&&a.length()>0)?a.optJSONObject(0):null;if(st!=null){applyEntitlements(st);if(accessDenied(st)){runOnUiThread(()->showAccessExpiredDialog(accessDeniedMessage(st)));return;}}runOnUiThread(allowedAction);}public void err(String e){runOnUiThread(allowedAction);}});
 }
 boolean isAccessExpiredResponse(JSONObject j){if(j==null)return false;int st=j.optInt("status",0);String m=j.optString("message","").toLowerCase(java.util.Locale.ROOT);return st==403||m.contains("teste grátis terminou")||m.contains("teste gratis terminou")||m.contains("assinatura inativa")||m.contains("assinatura venceu")||m.contains("plano vencido")||m.contains("escolha um plano");}
 void launchOnlinePlayer(Intent in){if(in!=null&&!tvMode&&CastHelper.isConnected(this)){String cu=in.getStringExtra("url"),ct=in.getStringExtra("title");boolean cl=in.getBooleanExtra("live",false);if(cu!=null&&!cu.trim().isEmpty()){CastHelper.cast(this,cu,ct,cl,null);return;}}String did=deviceId();Api.post("stream_session",Api.m("user_id",uid,"device_id",did,"action","acquire"),new Api.CB(){public void ok(JSONObject j){JSONArray a=j.optJSONArray("result");if(j.optInt("status")!=200||a==null||a.length()==0){runOnUiThread(()->{String m=j.optString("message","Não foi possível iniciar a reprodução.");if(isAccessExpiredResponse(j))showAccessExpiredDialog(m);else showAppNotice(m,true);});return;}runOnUiThread(()->{in.putExtra("gp_user_id",uid);in.putExtra("gp_device_id",did);startActivity(in);});}public void err(String x){runOnUiThread(()->showAppNotice(x==null||x.isEmpty()?"Não foi possível validar o limite de telas.":x,true));}});}
